WITH not_flagged AS (SELECT s.* FROM products s WHERE NOT EXISTS (SELECT 1 FROM store_sales c WHERE c.product_id = s.id AND c.sale_date <= s.launch_date)) SELECT s.id, s.product_name, s.stock_qty, s.launch_date, s.supplier_id, CASE WHEN product_name RLIKE '^(Laptop Pro 14|Desk Lamp)$' THEN 'GROUP_B' WHEN product_name RLIKE '^(wireless mouse|USB-C Hub)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS product_name_zone, (SELECT MAX(t2.price) FROM products t2 WHERE t2.supplier_id = s.supplier_id) AS max_product_price FROM not_flagged s ORDER BY stock_qty DESC, launch_date
